<script setup lang="ts">
import { onBeforeUnmount, onMounted } from 'vue'
import AppIcon from '../../../../../shared/components/layout/AppIcon.vue'
import TeamLoanForm from '../form/TeamLoanForm.vue'
import type { LoanPayload, RepaymentPayload, TeamLoan, TeamMember } from '../../types/teamLoan'
const props = defineProps<{ open: boolean; mode: 'create' | 'repay' | 'void'; loan: TeamLoan | null; members: TeamMember[]; submitting: boolean; error: string }>()
const emit = defineEmits<{ close: []; submitLoan: [LoanPayload]; submitRepayment: [RepaymentPayload]; voidLoan: [string] }>()
function keydown(event: KeyboardEvent) { if (props.open && event.key === 'Escape' && !props.submitting) emit('close') }
onMounted(() => window.addEventListener('keydown', keydown)); onBeforeUnmount(() => window.removeEventListener('keydown', keydown))
</script>
<template><Teleport to="body"><div v-if="open" class="backdrop" @click.self="!submitting && emit('close')"><section class="modal modal-card" role="dialog" aria-modal="true"><header><div><span>KEUANGAN · KASBON TIM</span><h2>{{ mode === 'create' ? 'Catat kasbon tim' : mode === 'repay' ? 'Catat pembayaran' : 'Koreksi kasbon' }}</h2><p v-if="mode === 'create'">Saldo kas awal dianggap Rp0.</p></div><button type="button" aria-label="Tutup" :disabled="submitting" @click="emit('close')"><AppIcon name="x" :size="19" /></button></header><TeamLoanForm :mode="mode" :loan="loan" :members="members" :submitting="submitting" :error="error" @submit-loan="emit('submitLoan',$event)" @submit-repayment="emit('submitRepayment',$event)" @void-loan="emit('voidLoan',$event)" /></section></div></Teleport></template>
<style scoped>.backdrop{position:fixed;z-index:100;inset:0;display:grid;place-items:center;overflow:auto;padding:22px;background:#000a;backdrop-filter:blur(5px)}.modal{width:min(100%,660px);max-height:92vh;overflow:auto;border:1px solid #3b3e38;border-radius:15px;background:#20221f;color:#f0f2ed}.modal header{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;gap:18px;padding:21px 24px 17px;border-bottom:1px solid #ffffff12;background:rgba(32,34,31,.96);backdrop-filter:blur(10px)}header span{color:#a3aa98;font-size:9px;font-weight:700;letter-spacing:1px}.modal h2{margin:7px 0 4px;font:700 20px Manrope,sans-serif}.modal p{margin:0;color:#9ea49a;font-size:11px}.modal header button{width:34px;height:34px;display:grid;place-items:center;flex:none;border:1px solid #ffffff16;border-radius:50%;background:transparent;color:#cdd1c9}@media(max-width:520px){.backdrop{display:block;padding:0;background:#181a17}.modal{width:100%;height:100dvh;max-height:100dvh;min-height:100vh;border:0;border-radius:0;padding-bottom:env(safe-area-inset-bottom)}.modal header{padding:20px 17px 16px}}</style>
